 p.write_bytes(b'\xffA\nA\n');stats=m['remove_duplicates'](str(p),comparison_mode='case-sensitive',show_progress=False,output_file=str(out));assert stats['duplicates_removed']==1;cases['invalid_utf8_collapses_distinct_lines']={'input_hex':p.read_bytes().hex(),'output_hex':out.read_bytes().hex(),'duplicates_removed':stats['duplicates_removed'],'detected_encoding':m['detect_encoding'](str(p))}
