 p.write_bytes(b'last-no-newline');m['remove_duplicates'](str(p),comparison_mode='case-sensitive',show_progress=False,output_file=str(out));assert out.read_bytes()==b'last-no-newline\n';cases['no_duplicate_still_changes_trailing_newline']={'output_hex':out.read_bytes().hex()}
 score=m['calculate_similarity']('red','red green blue');assert score==1;cases['documented_jaccard_is_overlap_coefficient']={'observed':score,'jaccard_oracle':1/3}
