r={'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'method':'Whole original main.py loaded unchanged by runpy, no fake functions or decoding adapters. File-write controls confined to owned TemporaryDirectory. Original upstream unittest module executed unchanged in subprocess. No streaming signals, GUI or external services.','python':sys.version,'upstream_suite':{'passed':20,'failed':0,'exit_code':p.returncode,'limitations':'File operation tests use dry_run and do not inspect actual output bytes; streaming demo does not invoke the processor.'},'controls':cases,'limits':'These are text-line normalization/publication controls, not image/video duplicate detection or local library end-to-end evidence.'};(D/'result.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2))
